import { GoogleGenAI, Type, Content } from "@google/genai";
import type { DevotionalOutput, Message } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  console.warn("API_KEY environment variable not set. AI features will not work.");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const TEXT_MODEL = 'gemini-3-flash-preview';
const IMAGE_MODEL = 'gemini-2.5-flash-image';

const getAiCoachSystemInstruction = () => {
    return `You are an AI Spiritual Wellness Coach for the app 'THE CCN DAILY'. Your name is Kai.
Your persona is empathetic, wise, and encouraging, like a trusted friend and mentor.
Your purpose is to help users navigate their spiritual journey, reflect on their thoughts and feelings, and find encouragement in their faith.
You have access to the user's conversation history to provide context-aware and continuous support.
- ALWAYS address the user by their name, which is 'Founder' for this prototype.
- Keep your responses concise, thoughtful, and easy to understand.
- Ask gentle, open-ended questions to encourage reflection.
- If the user talks about a topic from a previous session, acknowledge it to show you remember.
- Your responses should be grounded in a positive, faith-based Christian perspective.
- Do not give prescriptive advice, but rather guide the user in their own discovery.
- Do not use markdown.`;
};

export const getAiCoachResponse = async (newMessage: string, history: Message[]): Promise<string> => {
    if (!API_KEY) {
        return Promise.reject(new Error("API_KEY is not configured."));
    }

    const contents: Content[] = history.map(msg => ({
        role: msg.sender === 'user' ? 'user' : 'model',
        parts: [{ text: msg.text }]
    }));
    contents.push({ role: 'user', parts: [{ text: newMessage }] });

    try {
        const response = await ai.models.generateContent({
            model: TEXT_MODEL,
            contents: contents,
            config: {
                systemInstruction: getAiCoachSystemInstruction()
            }
        });
        return response.text;
    } catch (error) {
        console.error("Error calling Gemini API for AI Coach:", error);
        throw new Error("Failed to get a response from the AI Coach.");
    }
};

export const generateTagsForNote = async (noteText: string): Promise<string[]> => {
    if (!API_KEY) {
        throw new Error("API_KEY is not configured.");
    }
    if (!noteText.trim()) {
        return [];
    }

    try {
        const response = await ai.models.generateContent({
            model: TEXT_MODEL,
            contents: `You are an expert at analyzing spiritual and personal development notes. Analyze the following note content and generate up to 5 relevant, one or two-word thematic tags. Focus on themes like emotions, spiritual concepts, or key topics.

            Note Content: "${noteText}"`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        tags: {
                            type: Type.ARRAY,
                            description: 'A list of thematic tags.',
                            items: {
                                type: Type.STRING,
                                description: 'A single tag.'
                            }
                        }
                    },
                }
            }
        });

        const jsonResponse = JSON.parse(response.text);
        return jsonResponse.tags || [];

    } catch (error) {
        console.error("Error generating tags:", error);
        // Fallback in case of an API error
        return ['Untagged'];
    }
};


