        ## INSPIRATION THEME ##
        Based on user context: Courage, Leadership, and seeking clarity.

        ## USER CONTEXT ##
        userName: ${userContext.name}
        userContext: The user has been taking notes on "courage" and "leadership" and is praying for "clarity for the project".
        `;

        const response = await ai.models.generateContent({
            model: TEXT_MODEL,
            contents: prompt,
            config: {
                systemInstruction: DEVOTIONAL_SYSTEM_INSTRUCTION,
                responseMimeType: "application/json",
            }
        });

        const devotionalObject = JSON.parse(response.text);
