            const url = await generateQuoteImage(prompt + " Cinematic style, 4k, meditative background, no text.");
            setGeneratedUrl(url);
        } catch (e) {
            alert("Image generation failed. Ensure your API key is active.");
        } finally {
            setIsGenerating(false);
        }
