                <h1 className="text-4xl font-black text-brand-text-primary flex items-center gap-4">
                    <PaintBrushIcon className="w-10 h-10 text-brand-accent"/>
                    Visual Sanctuary
                </h1>
                <p className="text-brand-text-secondary">Phase 5.2: Paint your meditation space using AI.</p>
            </div>

            <div className="flex-1 grid grid-cols-1 lg:grid-cols-4 gap-6 min-h-0">
                <div className="lg:col-span-1 space-y-6">
                    <Card className="h-full">
                        <h2 className="text-lg font-bold text-brand-text-primary mb-4">Design Space</h2>
                        <p className="text-xs text-brand-text-secondary mb-4">Describe the atmosphere you want to inhabit during your spiritual journey.</p>
                        <textarea 
                            value={prompt}
                            onChange={(e) => setPrompt(e.target.value)}
                            className="w-full h-32 p-3 bg-brand-secondary border border-brand-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-brand-accent"
                            placeholder="e.g., Mount Zion at dawn..."
                        />
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className="w-full mt-4 py-3 bg-brand-accent text-white rounded-xl font-bold flex items-center justify-center gap-2 hover:scale-[1.02] transition-transform disabled:opacity-50"
                        >
                            {isGenerating ? <SpinnerIcon className="w-5 h-5"/> : <><SparklesIcon className="w-5 h-5"/> Generate Space</>}
                        </button>

                        <div className="mt-8 pt-8 border-t border-brand-border">
                            <h3 className="text-xs font-black uppercase text-brand-text-secondary tracking-widest mb-4">Phase 6 Preview</h3>
                            <div className="p-4 bg-brand-dark rounded-xl border border-brand-border opacity-50 grayscale">
                                <p className="text-[10px] font-bold text-brand-accent mb-1">Veo Cinematic Video</p>
                                <p className="text-[10px] text-brand-text-secondary leading-tight">Motion-based sanctuaries with ambient soundscapes coming next.</p>
                            </div>
                        </div>
                    </Card>
                </div>

                <div className="lg:col-span-3">
                    <Card className="h-full flex flex-col items-center justify-center relative overflow-hidden group p-0 border-none bg-brand-dark">
                        {!generatedUrl && !isGenerating && (
                            <div className="text-center p-12 max-w-md">
                                <div className="w-20 h-20 bg-brand-accent/10 rounded-full flex items-center justify-center mx-auto mb-6">
                                    <PaintBrushIcon className="w-10 h-10 text-brand-accent opacity-20"/>
                                </div>
                                <h3 className="text-xl font-bold text-brand-text-primary mb-2">Awaiting Vision</h3>
                                <p className="text-sm text-brand-text-secondary leading-relaxed">Enter a prompt to create a unique meditation background. Each creation is stored in your personal sanctuary gallery.</p>
                            </div>
                        )}

                        {isGenerating && (
                            <div className="text-center">
                                <div className="relative w-24 h-24 mx-auto mb-6">
                                    <div className="absolute inset-0 border-4 border-brand-accent/20 rounded-full"></div>
                                    <div className="absolute inset-0 border-t-4 border-brand-accent rounded-full animate-spin"></div>
                                    <SparklesIcon className="w-8 h-8 text-brand-accent absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse"/>
                                </div>
                                <p className="text-brand-accent font-black uppercase tracking-[0.2em] text-xs">Architecting Sanctuary...</p>
                            </div>
                        )}

                        {generatedUrl && (
                            <div className="w-full h-full animate-fade-in">
                                <img src={generatedUrl} className="w-full h-full object-cover" alt="Generated Sanctuary" />
                                <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-end p-8">
                                    <div className="flex justify-between items-center">
                                        <div>
                                            <p className="text-white font-bold text-lg">Your Spiritual Space</p>
                                            <p className="text-white/60 text-xs truncate max-w-md">{prompt}</p>
                                        </div>
                                        <div className="flex gap-2">
                                            <a href={generatedUrl} download="sanctuary.png" className="p-3 bg-white/20 backdrop-blur-md rounded-full text-white hover:bg-white/40">
                                                <DownloadIcon className="w-5 h-5"/>
