    if (!deepQuestion.trim()) return;
    setIsThinking(true);
    setDeepInsight('');
    try {
      const result = await getDeepTheologicalInsight(deepQuestion);
      setDeepInsight(result);
    } catch (e) {
      alert("Thinking test failed.");
